//go:build amd64

package floats

// The AVX2+FMA kernels of the DCT-IV twiddle passes (twiddle.go), generated by
// go-asmgen (twiddle_amd64_gen.go) into twiddle_amd64.s: four complex numbers per
// step, for a CPU with the AVX2+FMA of the other kernels (hasAVX2FMA,
// kernels_amd64.go); the portable loops otherwise. The gather kernels do
// (n/8)*4 of the n/2 complex numbers and the Go code finishes the rest; the scatter
// kernels cover every output when n >= 8 (two ends of four, which may meet and
// rewrite the same values) and shorter ones run the portable loop. No kernel keeps
// a pointer: go:noescape.
//
//go:noescape
func cmulGather64AVX2(dst, x, tw []float64)

//go:noescape
func cmulGatherFrom32AVX2(dst []float64, x []float32, tw []float64)

//go:noescape
func cmulScatter64AVX2(dst, c, tw []float64, f float64)

//go:noescape
func cmulScatterTo32AVX2(dst []float32, c, tw []float64, f float64)

func cmulGather(dst, x, tw []float64) {
	if !hasAVX2FMA {
		cmulGatherTail(dst, x, tw, 0)
		return
	}
	cmulGather64AVX2(dst, x, tw)
	cmulGatherTail(dst, x, tw, (len(tw)/2)&^3)
}

func cmulGather32(dst []float64, x []float32, tw []float64) {
	if !hasAVX2FMA {
		cmulGather32Tail(dst, x, tw, 0)
		return
	}
	cmulGatherFrom32AVX2(dst, x, tw)
	cmulGather32Tail(dst, x, tw, (len(tw)/2)&^3)
}

func cmulScatter(dst, c, tw []float64, f float64) {
	if !hasAVX2FMA || len(tw) < 8 {
		cmulScatterRef(dst, c, tw, f)
		return
	}
	cmulScatter64AVX2(dst, c, tw, f)
}

func cmulScatter32(dst []float32, c, tw []float64, f float64) {
	if !hasAVX2FMA || len(tw) < 8 {
		cmulScatter32Ref(dst, c, tw, f)
		return
	}
	cmulScatterTo32AVX2(dst, c, tw, f)
}
